package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class EmployeeOnboardingAcceptance {
 static String api(String id){return "/api/openservice/hr-cases/"+id+"/onboarding";}
 static String tasks(String id){return "/api/openservice/records/sc_request/"+id+"/work-tasks";}
 static String[] setup(WorkflowSupport h)throws Exception{var ids=EmployeeCasesAcceptance.setup(h);h.account("OnboardIT","agent");h.account("OnboardFacilities","agent");String it=h.add("sys_user_group").get("sys_id").toString(),fac=h.add("sys_user_group").get("sys_id").toString();RecordScopesAcceptance.member(h,it,FieldDispatchAcceptance.uid(h,"OnboardIT"),true);RecordScopesAcceptance.member(h,fac,FieldDispatchAcceptance.uid(h,"OnboardFacilities"),true);String id=EmployeeCasesAcceptance.create(h,ids[0],"EmployeeAgent");return new String[]{id,it,fac,ids[1]};}
 static Map<String,Object> body(WorkflowSupport h,String id,String operation)throws Exception{var p=get(h,api(id),"admin");return map("operation",operation,"revision",object(p.get("plan")).get("revision"),"record_revision",Integer.parseInt(object(p.get("parent")).get("sys_mod_count").toString()));}
 static Map<String,Object> addBody(WorkflowSupport h,String id,String group)throws Exception{var b=body(h,id,"add");b.putAll(map("display_title","Prepare your workplace <script>","summary","Department provisioning","details","DEPARTMENT instructions only; do not forward HR details","group_id",group));return b;}
 static Map<String,Object> send(WorkflowSupport h,String id,Map<String,Object> b,String user)throws Exception{return result(h.json("POST",api(id),b,auth(user)));}
 static List<Map<String,Object>> bindings(WorkflowSupport h,String id)throws Exception{try(var db=h.store.open()){return db.all("SELECT * FROM os_hr_onboarding_work WHERE parent_id=? ORDER BY ordinal",id);}}
 static Map<String,Object> taskBody(WorkflowSupport h,String child,String operation)throws Exception{var p=get(h,tasks(child),"admin");var t=objects(p.get("tasks")).getFirst();var b=map("operation",operation,"revision",t.get("revision"),"record_revision",Integer.parseInt(object(p.get("parent")).get("sys_mod_count").toString()),"task_id",t.get("task_id"));if(operation.equals("complete"))b.put("outcome","DEPARTMENT internal completion detail");if(operation.equals("requeue"))b.put("reason","Reassign departed employee");return b;}
 static Map<String,Object> task(WorkflowSupport h,String child,String operation,String user)throws Exception{return result(h.json("POST",tasks(child),taskBody(h,child,operation),auth(user)));}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var create=h.get("/record/incident/new",auth("HrAgent"));assertEquals(200,create.statusCode());assertFalse(html(create).contains("Plan employee onboarding"));String ordinary=h.add("incident").get("sys_id").toString();assertFalse(html(h.get("/record/incident/"+ordinary,auth("HrAgent"))).contains("Plan employee onboarding"));assertTrue(objects(object(get(h,api(id),"HrAgent").get("plan")).get("steps")).isEmpty());send(h,id,addBody(h,id,ids[1]),"HrAgent");send(h,id,addBody(h,id,ids[2]),"HrAgent");assertTrue(objects(get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent").get("onboarding")).isEmpty());var launch=body(h,id,"launch");send(h,id,launch,"HrAgent");assertEquals(409,h.json("POST",api(id),launch,auth("HrAgent")).statusCode());var work=bindings(h,id);assertEquals(2,work.size());String first=work.getFirst().get("child_id").toString(),second=work.getLast().get("child_id").toString();assertEquals(409,h.json("POST",tasks(second),taskBody(h,second,"claim"),auth("OnboardFacilities")).statusCode());assertEquals(false,objects(get(h,tasks(second),"OnboardFacilities").get("tasks")).getFirst().get("ready"));assertEquals(409,h.json("PATCH","/api/now/table/hr_case/"+id,map("state","cancelled"),auth("HrAgent")).statusCode());assertEquals(409,h.json("DELETE","/api/now/table/hr_case/"+id,map(),auth("admin")).statusCode());assertEquals(409,h.json("DELETE","/api/now/table/sc_request/"+first,map(),auth("admin")).statusCode());assertEquals(409,h.json("PATCH","/api/now/table/sc_request/"+first,map("state","complete"),auth("OnboardIT")).statusCode());
  task(h,first,"claim","OnboardIT");assertEquals("fulfilling",object(get(h,tasks(first),"OnboardIT").get("parent")).get("state"));task(h,first,"complete","OnboardIT");assertEquals("complete",object(get(h,tasks(first),"OnboardIT").get("parent")).get("state"));assertEquals("complete",objects(get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent").get("onboarding")).getFirst().get("status"));assertFalse(JSON.writeValueAsString(get(h,api(id),"HrAgent")).contains("internal completion detail"));task(h,second,"claim","OnboardFacilities");task(h,second,"requeue","admin");assertEquals("pending",bindings(h,id).getLast().get("status"));task(h,second,"claim","OnboardFacilities");task(h,second,"complete","OnboardFacilities");new Store(h.environment);assertEquals(List.of("complete","complete"),objects(get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent").get("onboarding")).stream().map(x->x.get("status")).toList());assertEquals(204,h.json("DELETE","/api/now/table/sc_request/"+first,map(),auth("admin")).statusCode());assertEquals(2,objects(get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent").get("onboarding")).size());assertEquals(409,h.json("POST","/api/openservice/import/sc_request?dry_run=false",List.of(map("sys_id",first,"short_description","Reused ID")),auth("admin")).statusCode());result(h.json("PATCH","/api/now/table/hr_case/"+id,map("state","working"),auth("HrAgent")));result(h.json("PATCH","/api/now/table/hr_case/"+id,map("state","closed"),auth("HrAgent")));assertEquals(false,get(h,api(id),"HrAgent").get("can_manage"));assertEquals(409,h.json("POST",api(id),body(h,id,"launch"),auth("HrAgent")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/hr_case/"+id,map(),auth("admin")).statusCode());assertEquals(200,h.get("/api/now/table/sc_request/"+second,auth("OnboardFacilities")).statusCode());assertEquals(404,h.get("/api/now/table/sc_request/"+second,auth("HrAgent")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_hr_onboarding WHERE parent_id=?",id));assertEquals(2,db.count("SELECT COUNT(*) FROM os_hr_onboarding_work WHERE parent_id=?",id));}
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var add=addBody(h,id,ids[1]);for(String user:List.of("OnboardIT","HrOutsider","EmployeeAgent")){assertEquals(404,h.get(api(id),auth(user)).statusCode());assertEquals(404,h.json("POST",api(id),add,auth(user)).statusCode());}assertEquals(403,h.get(api(id),auth("EmployeeOne")).statusCode());send(h,id,add,"HrAgent");send(h,id,body(h,id,"launch"),"HrAgent");var binding=bindings(h,id).getFirst();String child=binding.get("child_id").toString(),taskId=binding.get("task_id").toString(),file=Values.id();assertEquals(302,h.protectedForm("/record/sc_request/"+child+"/note",map("body","DEPARTMENT PRIVATE JOURNAL"),auth("OnboardIT")).statusCode());try(var db=h.store.open()){db.update("INSERT INTO os_attachment(sys_id,record_id,name,content,content_type) VALUES(?,?,?,?,?)",file,child,"department.txt","DEPARTMENT FILE".getBytes(),"text/plain");db.connection.commit();}
  for(String user:List.of("HrAgent","EmployeeAgent","OnboardFacilities","EmployeeReader")){for(String path:List.of("/api/now/table/sc_request/"+child,"/record/sc_request/"+child,"/attachment/"+file))assertEquals(404,h.get(path,auth(user)).statusCode(),path);assertFalse(html(h.get("/workspace/sc_request",auth(user))).contains("DEPARTMENT instructions"));assertFalse(html(h.get("/audit",auth(user))).contains("DEPARTMENT PRIVATE JOURNAL"));assertFalse(html(h.get("/export/sc_request",auth(user))).contains(child));}
  var employee=get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent");String text=JSON.writeValueAsString(employee);assertFalse(text.contains(child));assertFalse(text.contains("DEPARTMENT"));assertEquals(Set.of("display_title","status"),objects(employee.get("onboarding")).getFirst().keySet());assertEquals(200,h.get("/attachment/"+file,auth("OnboardIT")).statusCode());assertFalse(JSON.writeValueAsString(get(h,"/api/now/table/sc_request/"+child,"OnboardIT")).contains("Employee-submitted"));assertEquals(0,get(h,"/api/openservice/work-tasks","HrAgent").get("total"));assertEquals(1,get(h,"/api/openservice/work-tasks","OnboardIT").get("total"));
  for(String action:List.of("configure","create","revise","cancel","waive"))assertEquals(409,h.json("POST",tasks(child),map("operation",action),auth("admin")).statusCode());for(String suffix:List.of("field-dispatch","field-visit")){String path="/api/openservice/records/sc_request/"+child+"/"+suffix+"/"+taskId;assertEquals(409,h.json("POST",path,map(),auth("OnboardIT")).statusCode());assertEquals(404,h.json("POST",path,map(),auth("HrAgent")).statusCode());}
  task(h,child,"claim","OnboardIT");RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"OnboardIT"),false);assertEquals(404,h.json("POST",tasks(child),taskBody(h,child,"complete"),auth("OnboardIT")).statusCode());assertEquals(404,h.get("/attachment/"+file,auth("OnboardIT")).statusCode());assertEquals(0,get(h,"/api/openservice/work-tasks","OnboardIT").get("total"));RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"OnboardIT"),true);
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"hr_case");}for(String change:List.of("read","update","write","groups")){var schema=new LinkedHashMap<>(original);String table="hr_case";Map<String,Object> saved=original;if(change.equals("groups")){table="sys_user_group";try(var db=h.store.open()){saved=Service.schema(db,table);}schema=new LinkedHashMap<>(saved);}if(change.equals("write"))schema.put("field_rules",map("description",map("type","string","write_roles",List.of("admin"))));else{var roles=new LinkedHashMap<>(object(schema.getOrDefault("record_roles",map())));roles.put(change.equals("groups")?"read":change,List.of("admin"));schema.put("record_roles",roles);}ReferencePickerAcceptance.writeSchema(h,table,schema);try{if(change.equals("groups"))assertTrue(object(get(h,api(id),"HrAgent").get("groups")).isEmpty());else{assertEquals(403,h.json("POST",api(id),body(h,id,"launch"),auth("HrAgent")).statusCode());if(!change.equals("read"))assertEquals(false,get(h,api(id),"HrAgent").get("can_manage"));}}finally{ReferencePickerAcceptance.writeSchema(h,table,saved);}}
  try(var db=h.store.open()){original=Service.schema(db,"sc_request");}var schema=new LinkedHashMap<>(original);var roles=new LinkedHashMap<>(object(original.getOrDefault("record_roles",map())));roles.put("update",List.of("admin"));schema.put("record_roles",roles);ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);try{assertEquals(403,h.json("POST",tasks(child),taskBody(h,child,"complete"),auth("OnboardIT")).statusCode());assertEquals("working",bindings(h,id).getFirst().get("status"));}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}task(h,child,"complete","OnboardIT");assertEquals(409,h.json("POST",tasks(child),taskBody(h,child,"claim"),auth("admin")).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(401,h.get(api(id),null).statusCode());assertEquals(405,h.json("PUT",api(id),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(id)+"?q=1",auth("admin")).statusCode());assertEquals(400,h.json("POST",api(id),body(h,id,"launch"),auth("admin")).statusCode());for(var change:List.of(map("operation","other"),map("extra",1),map("revision",-1),map("display_title",""),map("summary","x".repeat(161)),map("details","x".repeat(4001)),map("group_id",""))){var bad=addBody(h,id,ids[1]);bad.putAll(change);assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());}assertEquals(404,h.json("POST",api(id),addBody(h,id,Values.id()),auth("admin")).statusCode());var remove=body(h,id,"remove");remove.put("step_id",Values.id());assertEquals(404,h.json("POST",api(id),remove,auth("admin")).statusCode());var added=send(h,id,addBody(h,id,ids[1]),"admin");remove=body(h,id,"remove");remove.put("step_id",objects(object(added.get("plan")).get("steps")).getFirst().get("step_id"));send(h,id,remove,"HrAgent");assertTrue(objects(object(get(h,api(id),"HrAgent").get("plan")).get("steps")).isEmpty());send(h,id,addBody(h,id,ids[1]),"admin");for(String key:List.of("revision","record_revision")){var bad=body(h,id,"launch");bad.put(key,999);assertEquals(409,h.json("POST",api(id),bad,auth("admin")).statusCode());}assertEquals(400,h.protectedForm("/record/hr_case/"+id+"/onboarding",map("operation","launch","revision","bad"),auth("admin")).statusCode());
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"sc_request");}for(String restriction:List.of("read","create","write","initial")){var schema=new LinkedHashMap<>(original);if(restriction.equals("initial")){var states=new LinkedHashMap<String,Object>();states.put("fulfilling","Fulfilling");states.put("open","Open");states.put("complete","Complete");schema.put("states",states);}else if(restriction.equals("write"))schema.put("field_rules",map("description",map("type","string","write_roles",List.of("admin"))));else schema.put("record_roles",map(restriction,List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);try{assertEquals(restriction.equals("initial")?400:403,h.json("POST",api(id),body(h,id,"launch"),auth("HrAgent")).statusCode());assertEquals(0,bindings(h,id).size());assertEquals(0,object(get(h,api(id),"HrAgent").get("plan")).get("launched"));}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}}
  ProblemInvestigationsAcceptance.access(h,"sys_user_group",ids[1],"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,h.json("POST",api(id),body(h,id,"launch"),auth("HrAgent")).statusCode());ProblemInvestigationsAcceptance.access(h,"sys_user_group",ids[1],"workspace","");
  send(h,id,body(h,id,"launch"),"HrAgent");assertEquals(409,h.json("POST",api(id),addBody(h,id,ids[1]),auth("HrAgent")).statusCode());assertEquals(409,h.json("POST",api(id),body(h,id,"launch"),auth("HrAgent")).statusCode());var waive=body(h,id,"waive");waive.putAll(map("ordinal",1,"reason","Cancelled employee start; explicitly waived"));assertEquals(403,h.json("POST",api(id),waive,auth("HrAgent")).statusCode());for(Object n:List.of("1",0,21)){var bad=new LinkedHashMap<>(waive);bad.put("ordinal",n);assertEquals(400,h.json("POST",api(id),bad,auth("admin")).statusCode());}var missing=new LinkedHashMap<>(waive);missing.put("ordinal",2);assertEquals(404,h.json("POST",api(id),missing,auth("admin")).statusCode());String child=bindings(h,id).getFirst().get("child_id").toString();task(h,child,"claim","OnboardIT");waive=body(h,id,"waive");waive.putAll(map("ordinal",1,"reason","Cancelled employee start; explicitly waived"));var form=new LinkedHashMap<>(waive);assertEquals(302,h.protectedForm("/record/hr_case/"+id+"/onboarding",form,auth("admin")).statusCode());assertEquals("waived",bindings(h,id).getFirst().get("status"));var repeat=body(h,id,"waive");repeat.putAll(map("ordinal",1,"reason","Cannot waive twice"));assertEquals(409,h.json("POST",api(id),repeat,auth("admin")).statusCode());assertEquals(409,h.json("POST",tasks(child),taskBody(h,child,"claim"),auth("admin")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/sc_request/"+child,map(),auth("admin")).statusCode());assertEquals("waived",objects(get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent").get("onboarding")).getFirst().get("status"));result(h.json("PATCH","/api/now/table/hr_case/"+id,map("state","cancelled"),auth("HrAgent")));
 }
 static void concurrency(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];send(h,id,addBody(h,id,ids[1]),"HrAgent");send(h,id,addBody(h,id,ids[2]),"HrAgent");var launch=body(h,id,"launch");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return h.json("POST",api(id),launch,auth("HrAgent")).statusCode();});var b=pool.submit(()->{start.await();return h.json("POST",api(id),launch,auth("HrAgent")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}assertEquals(2,bindings(h,id).size());var waive=body(h,id,"waive");waive.putAll(map("ordinal",1,"reason","IT prerequisite explicitly waived"));send(h,id,waive,"admin");String child=bindings(h,id).getLast().get("child_id").toString();task(h,child,"claim","OnboardFacilities");task(h,child,"complete","OnboardFacilities");var done=body(h,id,"waive");done.putAll(map("ordinal",2,"reason","Already completed"));assertEquals(409,h.json("POST",api(id),done,auth("admin")).statusCode());
 }
 static void limits(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];for(int n=0;n<20;n++)send(h,id,addBody(h,id,ids[1]),"HrAgent");assertEquals(400,h.json("POST",api(id),addBody(h,id,ids[1]),auth("HrAgent")).statusCode());send(h,id,body(h,id,"launch"),"HrAgent");assertEquals(20,bindings(h,id).size());assertEquals(20,objects(get(h,EmployeeCasesAcceptance.path(id,true),"EmployeeAgent").get("onboarding")).size());
 }
}
